# Cross-engine consistency: the R package must return exactly the same hex
# codes as the web engine (web/public/engine.js). The fixture is generated by
# `node web/test/make_fixture.mjs`; regenerate it after any engine change.

fx <- jsonlite::fromJSON(test_path("fixtures", "engine_cases.json"), simplifyVector = FALSE)

test_that("fixture and R engine are the same version", {
  expect_equal(fx$engine, loscolores:::LC_ENGINE_VERSION)
})

for (cs in fx$cases) {
  test_that(paste("same system as the web engine:", cs$name), {
    sys <- loscolores_system(unlist(cs$input), pivot = cs$pivot)
    expect_equal(sys$polos$black, cs$black)
    expect_equal(sys$polos$white, cs$white)
    expect_equal(sys$raw_5, unlist(cs$raw5))
    expect_equal(sys$log$law, unlist(cs$laws))
    expect_equal(loscolores:::get_dynamic_slate(sys), cs$slate)
    for (o in names(cs$cat5)) {
      expect_equal(sample_system(sys, "categorical", o, 5), unlist(cs$cat5[[o]]))
      expect_equal(sample_system(sys, "categorical", o, 8), unlist(cs$cat8[[o]]))
    }
    for (o in names(cs$seq9)) {
      expect_equal(sample_system(sys, "sequential", o, 9), unlist(cs$seq9[[o]]))
      expect_equal(sample_system(sys, "divergent", o, 11, "white"), unlist(cs$div11w[[o]]))
      expect_equal(sample_system(sys, "divergent", o, 11, "black"), unlist(cs$div11b[[o]]))
    }
    expect_equal(sample_system(sys, "categorical", "A", 5, grayscale = TRUE), unlist(cs$catGrey))
  })
}

test_that("laws hold on every fixture input", {
  for (cs in fx$cases) {
    sys <- loscolores_system(unlist(cs$input), pivot = cs$pivot)
    if (sys$anchor_origin == "input") expect_true(sys$raw_5[1] %in% sys$input)
    expect_equal(length(unique(sys$raw_5)), 5L)
    for (p in c(sys$polos$black, sys$polos$white)) {
      lab <- to_oklab(p)
      expect_lt(lab$c, 0.005)            # poles are neutral greys
    }
    L <- sort(to_oklab(c(sys$polos$black, sys$raw_5, sys$polos$white))$L)
    expect_gt(min(diff(L)), 0.05)
  }
})

test_that("old API keeps working", {
  sys <- set_loscolores("#096ED3", "#F9A730", "#F99DC2", "#303F47")
  expect_s3_class(sys, "lc_system")
  expect_length(sample_system(sys, "sequential", "Option_C", n = 100), 100)
  expect_s3_class(ggplot2::ggplot() + scale_fill_loscolores_cat() + theme_loscolores(), "ggplot")
  expect_identical(get_loscolores(), sys)
})
